<script setup>
import { computed, onMounted, ref } from 'vue';
import { useAppStore } from '../../stores/appStore';
import { useLessonsStore } from '../../stores/lessonsStore';
import LessonFormModal from '../modals/LessonFormModal.vue';
import ConfirmModal from '../modals/ConfirmModal.vue';
const app = useAppStore(), store = useLessonsStore(); const editing = ref(undefined), deleting = ref(null);
const visible = computed(() => store.lessons.value.filter(l => app.isTeacher.value || l.published === true));
onMounted(() => { if(!store.lessons.value.length) store.fetchLessons(); });
function open(l) { app.currentLessonId.value=l.id; app.lessonsScreen.value='lesson'; }
</script>
<template><section><div class="section-row"><div><h1 class="screen-title">{{ app.isTeacher.value ? 'Мои уроки' : 'Доступные уроки' }}</h1><p class="screen-subtitle">Ваши материалы для живой практики английского</p></div><div class="actions"><button class="btn btn-secondary" :disabled="store.isLoading.value" @click="store.fetchLessons">Обновить</button><button v-if="app.isTeacher.value" class="btn btn-primary" @click="editing=null">+ Создать урок</button></div></div><div v-if="store.isLoading.value" class="loading-state"><div class="spinner" />Загружаем уроки…</div><div v-else-if="!visible.length" class="empty-state"><h3>Уроков пока нет</h3><p>{{ app.isTeacher.value ? 'Создайте свой первый урок.' : 'Здесь появятся опубликованные материалы.' }}</p></div><div v-else class="lessons-grid"><article v-for="lesson in visible" :key="lesson.id" class="lesson-card"><div class="actions"><span class="badge badge-cards">{{ store.pluralizeCards(lesson.cards.length) }}</span><span v-if="app.isTeacher.value" class="badge" :class="lesson.published ? 'badge-published' : 'badge-draft'">{{ lesson.published ? 'Опубликован' : 'Черновик' }}</span></div><h2>{{ lesson.title }}</h2><small>{{ store.formatDate(lesson.createdAt) }}</small><div class="section-row"><button class="btn btn-ghost" @click="open(lesson)">Открыть урок →</button><div v-if="app.isTeacher.value" class="actions"><button class="icon-btn" aria-label="Редактировать урок" @click="editing=lesson">✎</button><button class="icon-btn danger" aria-label="Удалить урок" @click="deleting=lesson">✕</button></div></div></article></div><LessonFormModal v-if="editing !== undefined" :lesson="editing" @close="editing=undefined" @saved="editing=undefined; open($event)" /><ConfirmModal v-if="deleting" title="Удалить урок?" :message="deleting.title" :action="() => store.deleteLesson(deleting.id)" @close="deleting=null" /></section></template>
